/**
 * pdf-fonts.js
 * Embeds a Unicode subset of Noto Sans (Regular + Bold) into jsPDF so that
 * currency symbols outside the standard PDF font encoding render correctly.
 *
 * BUG THIS FIXES:
 * jsPDF's built-in "helvetica" font uses WinAnsi encoding, which has no
 * slot for the Indian Rupee sign (U+20B9) or several other currency
 * symbols. Any text containing them silently renders as whatever WinAnsi
 * happens to map that byte to -- which is why exported PDFs showed
 * "\u00b9" (superscript one) instead of "\u20b9" (Rupee sign, e.g. in
 * "\u20b910.00"). The on-screen app looked correct because browsers use
 * a real Unicode font; jsPDF does not, unless one is embedded.
 *
 * FIX: embed a real Unicode font (subset of Noto Sans, ~26KB each weight,
 * covering Latin + common currency symbols: $, \u00a3, \u00a5, \u20ac, \u20b9)
 * and use it for every string drawn in the PDF, instead of "helvetica".
 *
 * Usage (right after creating the jsPDF doc):
 *   const doc = new jsPDF({ ... });
 *   PdfFonts.register(doc);
 *   doc.setFont('NotoSans', 'normal'); // instead of doc.setFont('helvetica', 'normal')
 *   doc.setFont('NotoSans', 'bold');   // instead of doc.setFont('helvetica', 'bold')
 */
const PdfFonts = (() => {
  const REGULAR_BASE64 = "";
  const BOLD_BASE64 = "";

  let registered = false;

  function register(doc) {
    // jsPDF fonts are registered per jsPDF instance's VFS, so this must be
    // called once per `new jsPDF(...)` document, not just once globally.
    doc.addFileToVFS('NotoSans-Regular.ttf', REGULAR_BASE64);
    doc.addFont('NotoSans-Regular.ttf', 'NotoSans', 'normal');

    doc.addFileToVFS('NotoSans-Bold.ttf', BOLD_BASE64);
    doc.addFont('NotoSans-Bold.ttf', 'NotoSans', 'bold');

    registered = true;
  }

  return { register, get registered() { return registered; } };
})();

window.PdfFonts = PdfFonts;
